from qlib import *
import math
def gcd(a,b): return math.gcd(a,b)
def lcm(a,b): return a*b//gcd(a,b)
def nd(n): return len([d for d in range(1,n+1) if n%d==0])
P=math.pi
S=lambda s:F(s)
